// Each file is gzipped JSON in base64, decoded the first time its `data` is read; see the script.
import { gunzipSync } from "node:zlib";

type DataFile = { tag: string; hash: string; data: any };

function unpack(list: [tag: string, hash: string, blob: string][]): DataFile[] {
  return list.map(([tag, hash, blob]) => {
    let data: unknown;
    return {
      tag,
      hash,
      get data() {
        if (data === undefined) data = JSON.parse(gunzipSync(Buffer.from(blob, "base64")).toString("utf8"));
        return data;
      },
    };
  });
}

